from pwn import *
import binascii

# Constants from challenge.py
MAGIC = 73

def xor(x, y):
    return bytes([a ^ b for a, b in zip(x, y)])

def foo(x, y, z, w):
    return bytes([(a&b&c&d | a&(b^255)&(c^255)&d | a&(b^255)&c&(d^255) | a&b&(c^255)&(d^255) | (a^255)&b&(c^255)&d | (a^255)&b&c&(d^255)) for a, b, c, d in zip(x, y, z, w)])

def inverse_foo(output, y, z, w):
    """Find x such that foo(x,y,z,w) = output"""
    result = []
    for out, b, c, d in zip(output, y, z, w):
        for x in [0, 255]:
            test = (x&b&c&d | x&(b^255)&(c^255)&d | x&(b^255)&c&(d^255) | 
                   x&b&(c^255)&(d^255) | (x^255)&b&(c^255)&d | (x^255)&b&c&(d^255))
