from pwn import *

# Constants
MAGIC = 73

def guardian(x):
    """Checks if input matches the guardian pattern"""
    n = len(x) // MAGIC
    valid = True
    for i in range(n):
        block = x[i*MAGIC:(i+1)*MAGIC]
        # Block must be all 0x00 or all 0xFF
        if not (all(b == 0x00 for b in block) or all(b == 0xFF for b in block)):
            valid = False
            break
    return valid

def generate_solution(iv):
    total_size = MAGIC * len(iv)
    solution = bytearray(total_size)

    # For each block based on IV bit
    for i, bit in enumerate(iv):
        block_start = i * MAGIC
        block_end = (i + 1) * MAGIC

        # Set block based on IV bit
        if bit == '1':
            # For 1, we want this block to be inverse of previous
            if i == 0:
                solution[block_start:block_end] = [0xFF] * MAGIC
            else:
                prev_block = solution[(i-1)*MAGIC:i*MAGIC]
                curr_block = [0xFF if b == 0x00 else 0x00 for b in prev_block]
                solution[block_start:block_end] = curr_block
        else:
            # For 0, we want this block to be same as previous
            if i == 0:
                solution[block_start:block_end] = [0x00] * MAGIC
            else:
                prev_block = solution[(i-1)*MAGIC:i*MAGIC]
                solution[block_start:block_end] = prev_block

    # Verify solution satisfies guardian function
    assert guardian(solution), "Solution does not satisfy guardian function"
    return bytes(solution)

